ddl:
CREATE TABLE Role (
    Operation_permissions VARCHAR(255),
    Role_ID INTEGER PRIMARY KEY,
    Role_name VARCHAR(255)
);

CREATE TABLE Supervisory_department (
    Department_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255),
    Responsibility_description VARCHAR(255)
);

CREATE TABLE Resource (
    Name VARCHAR(255),
    Resource_code VARCHAR(255) PRIMARY KEY
);

CREATE TABLE Approval_document (
    Document_ID INTEGER PRIMARY KEY,
    Document_content VARCHAR(255),
    Document_name VARCHAR(255)
);

CREATE TABLE User (
    Email VARCHAR(255),
    Password VARCHAR(255),
    Role_ID INTEGER NOT NULL,
    User_ID INTEGER PRIMARY KEY,
    Username VARCHAR(255),
    FOREIGN KEY (Role_ID) REFERENCES Role(Role_ID)
);

CREATE TABLE Work_unit (
    Name VARCHAR(255),
    Responsibility_description VARCHAR(255),
    Supervisory_department_ID INTEGER NOT NULL,
    Work_unit_ID INTEGER PRIMARY KEY,
    FOREIGN KEY (Supervisory_department_ID) REFERENCES Supervisory_department(Department_ID)
);

CREATE TABLE Operation (
    Operating_user_ID INTEGER NOT NULL,
    Operation_ID INTEGER PRIMARY KEY,
    Operation_content VARCHAR(255),
    Operation_time DATETIME,
    FOREIGN KEY (Operating_user_ID) REFERENCES User(User_ID)
);

CREATE TABLE Resource_transaction_record (
    Budget_year INTEGER,
    Receiver_user_ID INTEGER NOT NULL,
    Record_ID INTEGER PRIMARY KEY,
    Resource_acquisition_value FLOAT,
    Resource_code VARCHAR(255) NOT NULL,
    Storage_location VARCHAR(255),
    Work_unit_ID INTEGER NOT NULL,
    FOREIGN KEY (Receiver_user_ID) REFERENCES User(User_ID),
    FOREIGN KEY (Resource_code) REFERENCES Resource(Resource_code),
    FOREIGN KEY (Work_unit_ID) REFERENCES Work_unit(Work_unit_ID)
);
